-- Core schema (SPEC §9). Plain Postgres: runs on Tiger Cloud and on embedded Postgres in tests.
-- Money is always integer cents (bigint). IDs are random text generated by the server.

create table patients (
  id                 text primary key,
  display_name       text not null,
  nessie_customer_id text,
  nessie_account_id  text,
  created_at         timestamptz not null default now()
);

-- Only an HMAC of the card token is stored; the token itself lives on the NFC tag.
create table card_tokens (
  token_hash text primary key,
  patient_id text not null references patients (id) on delete cascade,
  status     text not null default 'active' check (status in ('active', 'revoked')),
  created_at timestamptz not null default now()
);

create table providers (
  id                 text primary key,
  name               text not null,
  kind               text not null,
  nessie_merchant_id text,
  solana_wallet      text,
  created_at         timestamptz not null default now()
);

-- A paired browser (kiosk phone, provider phone, reviewer laptop). The cookie holds the secret.
create table devices (
  id           text primary key,
  role         text not null check (role in ('kiosk', 'provider', 'reviewer')),
  label        text not null,
  secret_hash  text not null unique,
  provider_id  text references providers (id),
  created_at   timestamptz not null default now(),
  last_seen_at timestamptz,
  check (role <> 'provider' or provider_id is not null)
);

-- Started by a card tap on a paired device. Kiosk sessions let the patient act;
-- provider sessions identify the patient for redemption.
create table sessions (
  secret_hash text primary key,
  device_id   text not null references devices (id) on delete cascade,
  patient_id  text not null references patients (id) on delete cascade,
  created_at  timestamptz not null default now(),
  expires_at  timestamptz not null,
  ended_at    timestamptz
);
create index sessions_device_idx on sessions (device_id);

create table documents (
  id          text primary key,
  patient_id  text not null references patients (id) on delete cascade,
  source      text not null check (source in ('scan', 'nessie_bill', 'nessie_purchase')),
  nessie_id   text,
  image       bytea,
  image_mime  text,
  status      text not null default 'extracting'
              check (status in ('extracting', 'extracted', 'unreadable', 'confirmed')),
  extraction  jsonb,
  confirmed   jsonb,
  warnings    text[] not null default '{}',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check (source = 'scan' or nessie_id is not null)
);
create index documents_patient_idx on documents (patient_id);

-- The community fund's budget: one row, updated atomically on approve / cancel / pay.
create table fund (
  id             text primary key default 'community',
  total_cents    bigint not null default 0 check (total_cents >= 0),
  reserved_cents bigint not null default 0 check (reserved_cents >= 0),
  paid_cents     bigint not null default 0 check (paid_cents >= 0),
  check (reserved_cents + paid_cents <= total_cents)
);

create table grants (
  id                 text primary key,
  patient_id         text not null references patients (id),
  document_id        text not null unique references documents (id),
  provider_id        text not null references providers (id),
  program_id         text not null,
  program_name       text not null,
  requested_cents    bigint not null check (requested_cents > 0),
  approved_cents     bigint check (approved_cents > 0),
  status             text not null default 'pending_review'
                     check (status in ('draft', 'pending_review', 'approved', 'rejected',
                                       'canceled', 'payment_pending', 'paid')),
  reviewer_device_id text references devices (id),
  decision_note      text,
  created_at         timestamptz not null default now(),
  decided_at         timestamptz,
  paid_at            timestamptz,
  updated_at         timestamptz not null default now(),
  check (approved_cents is null or approved_cents <= requested_cents),
  check (status not in ('approved', 'payment_pending', 'paid') or approved_cents is not null)
);
create index grants_status_idx on grants (status);

-- One row per external payment call (SPEC §8). Written BEFORE calling Nessie or broadcasting.
create table payment_attempts (
  id                     text primary key,
  grant_id               text not null references grants (id),
  rail                   text not null check (rail in ('nessie', 'solana')),
  idempotency_key        text not null unique,
  amount_cents           bigint,
  lamports               bigint,
  recipient              text not null,
  external_id            text,          -- Nessie purchase ID or Solana signature
  signed_tx              text,          -- base64 signed Solana transaction, persisted before broadcast
  last_valid_block_height bigint,
  status                 text not null default 'pending'
                         check (status in ('pending', 'confirmed', 'failed', 'expired')),
  error                  text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
-- At most one live (pending or confirmed) attempt per grant and rail: no double payments.
create unique index payment_attempts_one_live
  on payment_attempts (grant_id, rail)
  where status in ('pending', 'confirmed');

-- Fund ledger. Becomes a TimescaleDB hypertable in 002_timescale.sql.
-- grant_ref is an opaque reference (never a patient identifier).
create table fund_events (
  time             timestamptz not null default now(),
  type             text not null check (type in ('donation', 'reservation', 'release', 'payout', 'receipt')),
  amount_cents     bigint not null default 0,
  grant_ref        text,
  solana_signature text
);
create index fund_events_time_idx on fund_events (time desc);

insert into fund (id) values ('community');
